<?php
namespace App\Http\Controllers;use App\Collaboration\{CollaborationResourceReference,CollaborationResourceRegistry};use App\Http\Resources\WebhookDeliveryResource;use App\Jobs\DeliverWebhookJob;use App\Models\Webhook;use Illuminate\Http\Request;
final class WebhookDeliveryController extends Controller{public function __construct(private CollaborationResourceRegistry $registry){}public function index(Request $r,string $id){$w=$this->webhook($r,$id,'view');$f=$r->validate(['status'=>'nullable|in:pending,retrying,delivered,failed,cancelled','per_page'=>'nullable|integer|in:25,50,100']);return WebhookDeliveryResource::collection($w->deliveries()->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->latest()->paginate($f['per_page']??25)->withQueryString());}public function retry(Request $r,string $id,string $delivery){$w=$this->webhook($r,$id,'edit');abort_unless($w->enabled,422,'Webhook is disabled.');$d=$w->deliveries()->findOrFail($delivery);abort_unless($d->status==='failed',422,'Only final failed deliveries may be retried.');$d->update(['status'=>'pending','attempt_count'=>0,'response_status'=>null,'response_excerpt'=>null,'error_code'=>null,'error_message'=>null,'next_retry_at'=>null]);DeliverWebhookJob::dispatch($d->id)->afterCommit();return response()->json(['data'=>['deliveryId'=>(string)$d->id,'status'=>'queued']],202);}private function webhook(Request $r,string $id,string $ability):Webhook{return $this->registry->resolve($r->user(),new CollaborationResourceReference('webhook',$id),$ability)->resource;}}